{"implementation": "def solve(case):
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    last = attempts[-1]
    if last['success']:
        return {"action": "success", "reflection": last['reflection']}
    elif len(attempts) >= max_attempts:
        return {"action": "max_attempts", "failure_signature": last['failure_signature'], "reflection": last['reflection']}
